import{_ as t,o as s,c as i,ao as a}from"./chunks/framework.BDlucYFY.js";const g=JSON.parse('{"title":"Testing and CI","description":"","frontmatter":{},"headers":[],"relativePath":"developer/testing.md","filePath":"developer/testing.md","lastUpdated":null}'),n={name:"developer/testing.md"};function o(r,e,l,d,h,p){return s(),i("div",null,[...e[0]||(e[0]=[a(`<h1 id="Testing-and-CI" tabindex="-1">Testing and CI <a class="header-anchor" href="#Testing-and-CI" aria-label="Permalink to &quot;Testing and CI {#Testing-and-CI}&quot;">​</a></h1><h2 id="Test-suites" tabindex="-1">Test suites <a class="header-anchor" href="#Test-suites" aria-label="Permalink to &quot;Test suites {#Test-suites}&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;using Pkg; Pkg.test()&#39;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # GIModel + QuarkModelTransitions</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=GIPaper</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;using Pkg; Pkg.test()&#39;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # GIPaper</span></span></code></pre></div><p>The default GIModel suite is the quick one that CI runs. It includes the transition tests and <a href="https://github.com/JuliaTesting/Aqua.jl" target="_blank" rel="noreferrer">Aqua.jl</a> quality checks. Tests check invariants and independent limits (closed-form integrals, sum rules, agreement of the two solvers) rather than frozen numbers where possible.</p><p>Solver-convergence sweeps take a few minutes and run only on request. They include unequal-mass P-wave mixing comparisons between FD, adaptive HO, and common-β HO (<code>test/heavy/mixing_convergence.jl</code>). Energy convergence alone does not certify a mixing angle: cancellations can magnify small operator and wave errors. HO spin expectation values therefore refine the momentum-operator basis independently of the solved wave. The quick suite also checks these sandwiches against analytic-wave momentum integrals and sampled FD waves.</p><p>Run the sweeps with:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">GI_HEAVY_TESTS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">true</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;using Pkg; Pkg.test()&#39;</span></span></code></pre></div><h2 id="Full-verification" tabindex="-1">Full verification <a class="header-anchor" href="#Full-verification" aria-label="Permalink to &quot;Full verification {#Full-verification}&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/verify_packages.sh</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # both test suites</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/verify_project.sh</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # heavy tests, GIPaper tests, and every comparison report</span></span></code></pre></div><p><code>verify_project.sh</code> regenerates all reports in <code>GIPaper/reports/</code>. Review the diff of those files: a physics change shows up there first.</p><h2 id="Documentation" tabindex="-1">Documentation <a class="header-anchor" href="#Documentation" aria-label="Permalink to &quot;Documentation {#Documentation}&quot;">​</a></h2><p>The site is built in two stages.</p><ol><li><p><strong>Executed pages</strong> (Getting started, most of the Manual, all Tutorials) are written as Quarto notebooks in <code>docs/quarto/*.qmd</code>. <code>julia docs/render.jl</code> runs them with <a href="https://quarto.org" target="_blank" rel="noreferrer">Quarto</a> in the environment <code>docs/quarto/Project.toml</code> and writes Markdown with outputs and figures to <code>docs/src/</code>. These generated files are committed. Rendering everything takes about 20–30 minutes; pass file names to render only some pages:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs/render.jl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tutorials/charmonium.qmd</span></span></code></pre></div></li><li><p><strong>Site assembly</strong> runs no calculations:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=docs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;using Pkg; Pkg.instantiate()&#39;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=docs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs/make.jl</span></span></code></pre></div><p>Documenter resolves cross-references and API docstrings, and DocumenterVitepress builds the static site with its bundled Node.js. <code>DOCS_MD_ONLY=true</code> stops after the Markdown stage. Preview a full build with <code>npm run docs:dev</code> from <code>docs/</code>.</p></li></ol><p>Edit the <code>.qmd</code> file, never the generated <code>.md</code> next to it; generated pages have no &quot;Edit this page&quot; link. <code>docs/quarto/rendered.toml</code> records the hash of each source when it was rendered, and <code>make.jl</code> refuses to build when a source changed without re-rendering. The landing-page figures in <code>docs/src/public/home/</code> come from <code>docs/quarto/home_figures.jl</code>, which a full render also runs. <strong>Before a release, re-render all pages</strong> so the published outputs match the released code.</p><p>Pages under <strong>Recorded reports</strong> are copied from <code>GIPaper/reports/</code> at build time; regenerate the reports first if the physics changed.</p><h2 id="Continuous-integration" tabindex="-1">Continuous integration <a class="header-anchor" href="#Continuous-integration" aria-label="Permalink to &quot;Continuous integration {#Continuous-integration}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">workflow</th><th style="text-align:right;">runs</th><th style="text-align:right;">on</th></tr></thead><tbody><tr><td style="text-align:right;"><code>Test.yml</code>, <code>TestOnPRs.yml</code></td><td style="text-align:right;">both test suites</td><td style="text-align:right;">pushes to <code>main</code>, pull requests</td></tr><tr><td style="text-align:right;"><code>Documentation.yml</code></td><td style="text-align:right;">site assembly from the committed pages and deployment to GitHub Pages (no calculations)</td><td style="text-align:right;">pushes to <code>main</code>, tags, pull requests (preview)</td></tr><tr><td style="text-align:right;"><code>Lint.yml</code></td><td style="text-align:right;">offline link check of Markdown files</td><td style="text-align:right;">pushes, pull requests</td></tr><tr><td style="text-align:right;"><code>LearningSheets.yml</code></td><td style="text-align:right;">builds the course PDFs and publishes them to the <code>learning-sheets</code> release</td><td style="text-align:right;">changes under <code>LearningTrack/</code></td></tr><tr><td style="text-align:right;"><code>CompatHelper.yml</code>, <code>TagBot.yml</code></td><td style="text-align:right;">dependency bounds, release tags</td><td style="text-align:right;">scheduled</td></tr></tbody></table><p>Deployment uses the <code>DOCUMENTER_KEY</code> secret. Documentation for pull requests is deployed as a preview under <code>previews/PR&lt;number&gt;</code>.</p>`,18)])])}const u=t(n,[["render",o]]);export{g as __pageData,u as default};
